                        if (((SmAbs(emon.Port.CellsAt(scr, a + 6) - emon.Port.CellsAt(scr, b + 6)) * 100) <= (emon.Port.CellsAt(scr, a + 8) * 8)) && ((SmAbs(emon.Port.CellsAt(scr, a + 7) - emon.Port.CellsAt(scr, b + 7)) * 100) <= (emon.Port.CellsAt(scr, a + 8) * 8))) {
                            emon.Port.CellsSet(scr, a + 10, emon.Port.CellsAt(scr, a + 10) | 2);
                            emon.Port.CellsSet(scr, b + 10, emon.Port.CellsAt(scr, b + 10) | 4);
