    internal static int SmShareOk(int w, int h, int pw, int ph) {
        // 1 when a box w x h covers at most `sm-page-share` per mille of a page pw x ph.
        long lhs = unchecked(unchecked(((long) w) * ((long) h)) * ((long) 1000));
        long rhs = unchecked(unchecked(((long) pw) * ((long) ph)) * ((long) SmPageShare()));
        if (lhs <= rhs) {
            return 1;
        }
        return 0;
    }
    internal static int SmStamps(emon.Port.Cells pa, emon.Port.Cells pts, int p0, int p1, int pw, int ph, emon.Port.Cells scr, int n0) {
        // The stamp candidates of the paths [p0, p1): stroked, unfilled quadrilaterals with a border of at least `sm-stamp-width` of a chromatic ink, at least
        // 10 pt on a side and not covering more than `sm-page-share` of the page. Appended to `scr`; answers the candidates in all.
        int r = p0;
        int n = n0;
        int w = 0;
        int h = 0;
        int ink = 0;
        while (r < p1) {
            if ((SmStrokeOnly(pa, r) == 1) && (n < SmMaxCands())) {
                if (Evidence.PaGet(pa, r, Evidence.PfWidth()) >= SmStampWidth()) {
                    if (SmPtsQuad(pa, pts, r) == 1) {
                        ink = Evidence.PaGet(pa, r, Evidence.PfStroke());
                        w = Evidence.PaGet(pa, r, Evidence.PfX1()) - Evidence.PaGet(pa, r, Evidence.PfX0());
                        h = Evidence.PaGet(pa, r, Evidence.PfY1()) - Evidence.PaGet(pa, r, Evidence.PfY0());
                        if ((SmSpread(ink) > SmChroma()) && ((w >= 1000) && (h >= 1000))) {
                            if (SmShareOk(w, h, pw, ph) == 1) {
