                }
                i += 1;
            }
        }
        i = 0;
        while (i < ns) {
            a = 8 + (i * 7);
            w = emon.Port.CellsAt(tmp, a + 2) - emon.Port.CellsAt(tmp, a);
            h = emon.Port.CellsAt(tmp, a + 3) - emon.Port.CellsAt(tmp, a + 1);
            if ((emon.Port.CellsAt(tmp, a + 4) >= SmSigSegs()) && ((w >= SmSigMinW()) && ((w * 2) >= (h * 3)))) {
                cue = 0;
