    }
    internal static int SmGroupInside(emon.Port.Cells cg, emon.Port.Cells refs, emon.Port.Cells owords, int g, emon.Port.Cells scr, int c) {
        // 1 when the group has no text-layer or hidden word, has OCR words, and the centre of every one lies inside the candidate at record `c`.
        int no = Player.CgGet(cg, g, Player.CgfOcount());
        int of = Player.CgGet(cg, g, Player.CgfOfirst());
        int k = 0;
        int row = 0;
        if (Player.CgGet(cg, g, Player.CgfTcount()) > 0) {
            return 0;
        }
        if (Player.CgGet(cg, g, Player.CgfHcount()) > 0) {
            return 0;
        }
        if (no == 0) {
            return 0;
        }
        if (emon.Port.CellsAt(scr, c) == 0) {
            return 0;
        }
        while (k < no) {
            row = emon.Port.CellsAt(refs, ((of + k) * 2) + 1);
            if (SmInside(scr, c, (Evidence.OwGet(owords, row, Evidence.HdX0()) + Evidence.OwGet(owords, row, Evidence.HdX1())) / 2, (Evidence.OwGet(owords, row, Evidence.HdY0()) + Evidence.OwGet(owords, row, Evidence.HdY1())) / 2) == 0) {
                return 0;
            }
            k += 1;
        }
        return 1;
    }
    internal static int SmWordLen(emon.Port.Cells fw, int row) {
        return emon.Port.CellsAt(fw, (row * 24) + 12);
    }
    internal static int SmCx(emon.Port.Cells fw, int row) {
        return (emon.Port.CellsAt(fw, (row * 24) + 1) + emon.Port.CellsAt(fw, (row * 24) + 3)) / 2;
    }
    internal static int SmCy(emon.Port.Cells fw, int row) {
        return (emon.Port.CellsAt(fw, (row * 24) + 2) + emon.Port.CellsAt(fw, (row * 24) + 4)) / 2;
    }
    internal static int SmPushRun(emon.Port.Cells et, int ts, int tl) {
        int j = 0;
        while (j < tl) {
            emon.Port.CellsPush(et, emon.Port.CellsAt(et, ts + j));
            j += 1;
        }
        return 0;
    }
    internal static int SmCountMembers(emon.Port.Cells scr, int c, emon.Port.Cells fw, emon.Port.Cells gl, int page) {
        int nfw = emon.Port.CellsLen(fw) / 24;
        int w = 0;
        int n = 0;
        while (w < nfw) {
            if (emon.Port.CellsAt(fw, w * 24) == page) {
                if (SmMember(scr, c, fw, gl, w) == 1) {
                    n += 1;
                }
            }
            w += 1;
        }
        return n;
    }
    internal static int SmTextLayerText(emon.Port.Cells scr, int c, emon.Port.Cells fw, emon.Port.Cells gl, emon.Port.Cells et, int page) {
        // Append to `et` the words of the candidate at record `c`, in the text layer's order, one space between two words unless both are one glyph and no wider
        // apart than 1.4 times the mean step of the single glyphs (the arc text of a seal: a glyph a word, the spaces of the ring are no word).
        int nfw = emon.Port.CellsLen(fw) / 24;
        int w = 0;
        int prev = -1;
        int sum = 0;
        int cnt = 0;
        int d = 0;
        int mean = 0;
        while (w < nfw) {
            if (emon.Port.CellsAt(fw, w * 24) == page) {
                if (SmMember(scr, c, fw, gl, w) == 1) {
                    if (prev >= 0) {
                        if ((SmWordLen(fw, prev) == 1) && (SmWordLen(fw, w) == 1)) {
                            sum += SmAbs(SmCx(fw, w) - SmCx(fw, prev)) + SmAbs(SmCy(fw, w) - SmCy(fw, prev));
                            cnt += 1;
                        }
                    }
                    prev = w;
                }
            }
            w += 1;
        }
        if (cnt > 0) {
            mean = sum / cnt;
        }
        w = 0;
        prev = -1;
        while (w < nfw) {
            if (emon.Port.CellsAt(fw, w * 24) == page) {
                if (SmMember(scr, c, fw, gl, w) == 1) {
                    if (prev >= 0) {
                        d = SmAbs(SmCx(fw, w) - SmCx(fw, prev)) + SmAbs(SmCy(fw, w) - SmCy(fw, prev));
                        if (((SmWordLen(fw, prev) != 1) || (SmWordLen(fw, w) != 1)) || ((d * 10) > (mean * 14))) {
                            emon.Port.CellsPush(et, 32);
                        }
                    }
                    SmPushRun(et, emon.Port.CellsAt(fw, (w * 24) + 11), emon.Port.CellsAt(fw, (w * 24) + 12));
                    prev = w;
                }
            }
            w += 1;
        }
        return 0;
    }
    internal static int SmPage(emon.Port.Cells scr, int n, int page, emon.Port.Cells fw, emon.Port.Cells gl, emon.Port.Cells et, emon.Port.Cells cg, emon.Port.Cells refs, emon.Port.Cells owords, emon.Port.Cells sm) {
        // Keep the candidates of `page` (records 0..n-1 of `scr`) that hold something, write their `sl` rows and text, and flag the groups that are theirs.
        int ng = Player.CgCount(cg);
        int k = 0;
        int c = 0;
        int tl = 0;
        int oc = 0;
        int g = 0;
        int keep = 0;
        int row = 0;
        int ts = 0;
        int first = 0;
        int nref = 0;
        int conf = 0;
        int kind = 0;
        int j = 0;
        int o = 0;
        int c0 = 0;
        int gfl = 0;
        int live = 0;
        // 1. which candidates hold something
        while (k < n) {
            c = k * SmCw();
            kind = emon.Port.CellsAt(scr, c);
            tl = 0;
            oc = 0;
            if (kind != Player.PlsSignature()) {
                tl = SmCountMembers(scr, c, fw, gl, page);
            }
            emon.Port.CellsSet(scr, c + 11, tl);
            g = 0;
            while (g < ng) {
                if (Player.CgGet(cg, g, Player.CgfPage()) == page) {
                    if (SmGroupInside(cg, refs, owords, g, scr, c) == 1) {
                        oc += 1;
                    }
                }
                g += 1;
            }
            keep = 1;
            if (kind == Player.PlsSeal()) {
                if (((tl + oc) == 0) && ((emon.Port.CellsAt(scr, c + 10) & 3) != 3)) {
                    keep = 0;
                }
            }
            if (kind == Player.PlsStamp()) {
                if ((tl + oc) == 0) {
                    keep = 0;
                }
            }
            // a ring that is another's inner ring is part of that seal
            if ((emon.Port.CellsAt(scr, c + 10) & 4) != 0) {
                keep = 0;
            }
            if (keep == 0) {
                emon.Port.CellsSet(scr, c, 0);
            }
            k += 1;
        }
