        while (g < ng) {
            if (Player.CgGet(cg, g, Player.CgfPage()) == page) {
                live = 0;
                if (Player.CgGet(cg, g, Player.CgfTcount()) > 0) {
                    c0 = -2;
                    j = 0;
                    while ((j < Player.CgGet(cg, g, Player.CgfTcount())) && (c0 != -1)) {
                        row = emon.Port.CellsAt(refs, ((Player.CgGet(cg, g, Player.CgfTfirst()) + j) * 2) + 1);
                        c = SmWordCand(scr, n, fw, gl, row);
                        if (c < 0) {
                            c0 = -1;
                        } else {
                            if (c0 == -2) {
                                c0 = c;
                            }
                            if (c0 != c) {
                                c0 = -1;
                            }
                        }
                        j += 1;
                    }
                    if (c0 >= 0) {
                        live = 1;
                    }
                } else {
                    k = 0;
                    while (k < n) {
                        if (SmGroupInside(cg, refs, owords, g, scr, k * SmCw()) == 1) {
                            live = 1;
                        }
                        k += 1;
                    }
                }
                if (live == 1) {
                    gfl = Player.CgGet(cg, g, Player.CgfFlags());
                    Player.CgSet(cg, g, Player.CgfFlags(), gfl | Player.PlgInSeal());
                }
            }
            g += 1;
        }
