    internal static int SmPxDash(int c) {
        // 1 for the marks a ring puts between its phrases that the engine can read: a hyphen, a middle dot, a bullet, a star, a bar.
        if (c == 45) {
            return 1;
        }
        if (c == 183) {
            return 1;
        }
        if (c == 8226) {
            return 1;
        }
        if (c == 9733) {
            return 1;
        }
        if (c == 9679) {
            return 1;
        }
        return 0;
    }
    internal static int SmPxCased(int c) {
        // 1 for a lower case Latin letter, 2 for an upper case one, 0 for any other character.
        if ((c >= 97) && (c <= 122)) {
            return 1;
        }
        if ((c >= 223) && (c <= 255)) {
            return 1;
        }
        if ((c >= 65) && (c <= 90)) {
            return 2;
        }
        if ((c >= 192) && (c <= 222)) {
            return 2;
        }
        return 0;
    }
    internal static int SmPxNoisy(emon.Port.Cells et, int ts, int tl) {
        // 1 when a word has, inside it, a mark that is no part of a word (anything but a letter, a digit, a hyphen, a point, a comma, a colon or an apostrophe: `C!TY`) or a lone lower case
        // letter between upper case ones (`RiVERTON`): what the engine makes of a ring's letters when it is not sure, and what a seal's own text is not.
        int k = 1;
        int c = 0;
        while (k < (tl - 1)) {
            c = emon.Port.CellsAt(et, ts + k);
            if ((Sealfield.SfScript(c) == 0) && ((Sealfield.SfDigit(c) < 0) && ((c != 45) && ((c != 46) && ((c != 44) && ((c != 58) && (c != 39))))))) {
                return 1;
            }
            if ((SmPxCased(c) == 1) && ((SmPxCased(emon.Port.CellsAt(et, (ts + k) + 1)) == 2) && (SmPxCased(emon.Port.CellsAt(et, (ts + k) - 1)) == 2))) {
                return 1;
            }
            k += 1;
        }
        return 0;
    }
    public static int SmPxKeep(emon.Port.Cells et, emon.Port.Cells owords, int row) {
        // 1 when the OCR word `row` of a seal's reading is kept in its text: it has three letters or digits and the engine was at least 250 per mille sure of it, or one and 600, or six
        // and 150 (a long word the engine doubted is still a word; two letters it doubted are noise), or it is a lone separator the engine was sure of (a ring's bullet or dash: what the name is cut by).
        int ts = Evidence.OwGet(owords, row, Evidence.HdTstart());
        int tl = Evidence.OwGet(owords, row, Evidence.HdTlen());
        int conf = Evidence.OwGet(owords, row, Evidence.HdConf());
        int k = 0;
        int n = 0;
        while (k < tl) {
            if ((Sealfield.SfScript(emon.Port.CellsAt(et, ts + k)) > 0) || (Sealfield.SfDigit(emon.Port.CellsAt(et, ts + k)) >= 0)) {
                n += 1;
            }
            k += 1;
        }
        if ((n > 0) && (SmPxNoisy(et, ts, tl) == 1)) {
            return 0;
        }
        if ((n == 3) && (conf >= 450)) {
            return 1;
        }
        if ((n >= 4) && (conf >= 350)) {
            return 1;
        }
        if ((n >= 1) && (conf >= 600)) {
            return 1;
        }
        if ((n >= 6) && (conf >= 300)) {
            return 1;
        }
        if ((n == 0) && ((tl == 1) && ((conf >= 800) && (SmPxDash(emon.Port.CellsAt(et, ts)) == 1)))) {
            return 1;
        }
        return 0;
    }
    internal static int SmPxText(emon.Port.Cells et, emon.Port.Cells refs, emon.Port.Cells owords, int from, int cnt) {
        // Append to `et` the text of a pixel-read seal: the kept words (`sm-px-keep`) of the refs run [from, from + cnt), a space between two, each trimmed of what is not a letter or a
        // digit at its ends (`“PAID`); a lone separator is put between two words and never at an end of the text. Answers the code points appended.
        int start = emon.Port.CellsLen(et);
        int i = 0;
        int row = 0;
        int ts = 0;
        int tl = 0;
        int a = 0;
        int b = 0;
        int pend = 0;
        while (i < cnt) {
            row = emon.Port.CellsAt(refs, ((from + i) * 2) + 1);
            if (SmPxKeep(et, owords, row) == 1) {
                ts = Evidence.OwGet(owords, row, Evidence.HdTstart());
                tl = Evidence.OwGet(owords, row, Evidence.HdTlen());
                a = 0;
                while ((a < tl) && ((Sealfield.SfScript(emon.Port.CellsAt(et, ts + a)) == 0) && (Sealfield.SfDigit(emon.Port.CellsAt(et, ts + a)) < 0))) {
                    a += 1;
                }
                if (a == tl) {
                    pend = emon.Port.CellsAt(et, ts);
                } else {
                    b = tl;
                    while ((b > a) && ((Sealfield.SfScript(emon.Port.CellsAt(et, ts + (b - 1))) == 0) && (Sealfield.SfDigit(emon.Port.CellsAt(et, ts + (b - 1))) < 0))) {
                        b -= 1;
                    }
                    if (emon.Port.CellsLen(et) > start) {
                        emon.Port.CellsPush(et, 32);
                    }
                    if ((pend > 0) && (emon.Port.CellsLen(et) > start)) {
                        emon.Port.CellsPush(et, pend);
                        emon.Port.CellsPush(et, 32);
                    }
                    pend = 0;
                    SmPushRun(et, ts + a, b - a);
                }
            }
            i += 1;
        }
        return emon.Port.CellsLen(et) - start;
    }
    internal static int SmLo(int a, int b) {
        if (a < b) {
            return a;
        }
        return b;
    }
    internal static int SmHi(int a, int b) {
        if (a > b) {
            return a;
        }
        return b;
    }
    internal static int SmOverlapShare(int ax0, int ay0, int ax1, int ay1, int bx0, int by0, int bx1, int by1) {
        // The part of the smaller of two boxes that the other covers, per cent.
        int w = (SmLo(ax1, bx1) - SmHi(ax0, bx0)) / 100;
        int h = (SmLo(ay1, by1) - SmHi(ay0, by0)) / 100;
        int sa = ((ax1 - ax0) / 100) * ((ay1 - ay0) / 100);
        int sb = ((bx1 - bx0) / 100) * ((by1 - by0) / 100);
        int small = sa;
        if ((w <= 0) || (h <= 0)) {
            return 0;
        }
        if (sb < small) {
            small = sb;
        }
        if (small <= 0) {
            return 0;
        }
        return ((w * h) * 100) / small;
    }
    internal static int SmRaster(int page, emon.Port.Cells et, emon.Port.Cells cg, emon.Port.Cells refs, emon.Port.Cells owords, emon.Port.Cells sm) {
        // The `sl` rows of the seals and stamps that page units found in pixels (`emon.sealpx`): one for every group of `page` flagged `seal-px`, unless a candidate that is
        // already there (found in the vector paths) has its box (half of the smaller). Its text is `sm-px-text`'s, its colour the group's code, its words the group's. Answers the rows written.
        int ng = Player.CgCount(cg);
        int g = 0;
        int o = 0;
        int dup = 0;
        int made = 0;
        int ts = 0;
        int fl = 0;
        int kind = 0;
        int conf = 0;
        while (g < ng) {
            if ((Player.CgGet(cg, g, Player.CgfPage()) == page) && ((Player.CgGet(cg, g, Player.CgfFlags()) & Player.PlgSealPx()) != 0)) {
                dup = 0;
                o = 0;
                while (o < Player.SlCount(sm)) {
                    if (Player.SlGet(sm, o, 0) == page) {
                        if (SmOverlapShare(Player.SlGet(sm, o, 1), Player.SlGet(sm, o, 2), Player.SlGet(sm, o, 3), Player.SlGet(sm, o, 4), Player.CgGet(cg, g, Player.CgfX0()), Player.CgGet(cg, g, Player.CgfY0()), Player.CgGet(cg, g, Player.CgfX1()), Player.CgGet(cg, g, Player.CgfY1())) >= 50) {
                            dup = 1;
                        }
                    }
                    o += 1;
                }
                if (dup == 0) {
                    fl = Player.CgGet(cg, g, Player.CgfFlags());
                    kind = Player.PlsSeal();
                    if ((fl & Player.PlgSealStamp()) != 0) {
                        kind = Player.PlsStamp();
                    }
                    ts = emon.Port.CellsLen(et);
                    SmPxText(et, refs, owords, Player.CgGet(cg, g, Player.CgfOfirst()), Player.CgGet(cg, g, Player.CgfOcount()));
                    // a reading with no word kept is no text: the seal has none
                    conf = 600;
                    if (kind == Player.PlsStamp()) {
                        conf = 700;
                    }
                    if (Player.CgGet(cg, g, Player.CgfRot()) > 2) {
                        conf += 100;
                    }
                    if (emon.Port.CellsLen(et) > ts) {
                        conf += 100;
                    }
                    if (conf > 900) {
                        conf = 900;
                    }
                    o = Player.SlNew(sm, page, Player.CgGet(cg, g, Player.CgfX0()), Player.CgGet(cg, g, Player.CgfY0()), Player.CgGet(cg, g, Player.CgfX1()), Player.CgGet(cg, g, Player.CgfY1()), kind);
                    emon.Port.CellsSet(sm, (o * 16) + 9, conf);
                    emon.Port.CellsSet(sm, (o * 16) + 10, Player.CgGet(cg, g, Player.CgfOfirst()));
                    emon.Port.CellsSet(sm, (o * 16) + 11, Player.CgGet(cg, g, Player.CgfOcount()));
                    emon.Port.CellsSet(sm, (o * 16) + 12, 128);
                    emon.Port.CellsSet(sm, (o * 16) + 13, ts);
                    emon.Port.CellsSet(sm, (o * 16) + 14, emon.Port.CellsLen(et) - ts);
                    emon.Port.CellsSet(sm, (o * 16) + 15, Player.CgGet(cg, g, Player.CgfRot()));
                    made += 1;
                }
            }
            g += 1;
        }
        return made;
    }
    public static int SmFind(emon.Port.Cells pa, emon.Port.Cells pts, emon.Port.Cells gl, emon.Port.Cells fw, emon.Port.Cells et, emon.Port.Cells epages, emon.Port.Cells cg, emon.Port.Cells refs, emon.Port.Cells owords, int np, emon.Port.Cells sm, emon.Port.Cells scr, emon.Port.Cells tmp) {
        // The candidates of every page (see the head of this file) into `sm` (the `sl` arena), the text of their words appended to `et` (`sl` cells 13-14), and
        // the flag `plg-in-seal` on the groups of `cg` that are theirs. `scr` and `tmp` are scratch. Answers the candidates written.
        int npaths = Evidence.PaCount(pa);
        int p = 1;
        int pi = 0;
        int p0 = 0;
        int p1 = 0;
        int n = 0;
        int ep = 0;
        int pw = 61200;
        int ph = 79200;
        emon.Port.CellsDrop(sm, 0);
        while (p <= np) {
            while ((pi < npaths) && (Evidence.PaGet(pa, pi, Evidence.PfPage()) < p)) {
                pi += 1;
            }
            p0 = pi;
            while ((pi < npaths) && (Evidence.PaGet(pa, pi, Evidence.PfPage()) == p)) {
                pi += 1;
            }
            p1 = pi;
            if (p1 > p0) {
                ep = Evidence.EvPageRow(epages, p);
                if (ep >= 0) {
                    pw = Evidence.EpGet(epages, ep, Evidence.EpfWidth());
                    ph = Evidence.EpGet(epages, ep, Evidence.EpfHeight());
                }
                emon.Port.CellsDrop(scr, 0);
                emon.Port.CellsDrop(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                emon.Port.CellsPush(tmp, 0);
                n = SmRings(pa, pts, p0, p1, scr, tmp);
                n = SmStamps(pa, pts, p0, p1, pw, ph, scr, n);
                n = SmSignatures(pa, pts, fw, et, p, p0, p1, pw, ph, scr, n, tmp);
                if (n > 0) {
                    SmPage(scr, n, p, fw, gl, et, cg, refs, owords, sm);
                }
            }
            SmRaster(p, et, cg, refs, owords, sm);
            p += 1;
        }
        return Player.SlCount(sm);
    }
    internal static int SmAnchor(int kind) {
        // 1 for the kinds of top-level block a seal is placed by: the nodes of the flow that start somewhere on a page.
        if (kind == Model.NkHeading()) {
            return 1;
        }
        if (kind == Model.NkParagraph()) {
            return 1;
        }
        if (kind == Model.NkList()) {
            return 1;
        }
        if (kind == Model.NkTable()) {
            return 1;
        }
        if (kind == Model.NkFigure()) {
            return 1;
        }
        if (kind == Model.NkQuote()) {
            return 1;
        }
        if (kind == Model.NkCode()) {
            return 1;
        }
        if (kind == Model.NkNote()) {
            return 1;
        }
        if (kind == Model.NkFormula()) {
            return 1;
        }
        if (kind == Model.NkCaption()) {
            return 1;
        }
        return 0;
    }
    internal static int SmMin(int a, int b) {
        if (a < b) {
            return a;
        }
        return b;
    }
    internal static int SmMax(int a, int b) {
        if (a > b) {
            return a;
        }
        return b;
    }
    internal static int SmHit(emon.Port.Cells sm, int o, emon.Port.Cells orr, int r0) {
        // The area (square points) of candidate `o`'s box that the regions of the chain starting at `r0` cover, on its page.
        int r = r0;
        int w = 0;
        int h = 0;
        int area = 0;
        while (r >= 0) {
            if (Model.RegionPage(orr, r) == Player.SlGet(sm, o, 0)) {
                w = (SmMin(Model.RegionX1(orr, r), Player.SlGet(sm, o, 3)) - SmMax(Model.RegionX0(orr, r), Player.SlGet(sm, o, 1))) / 100;
                h = (SmMin(Model.RegionY1(orr, r), Player.SlGet(sm, o, 4)) - SmMax(Model.RegionY0(orr, r), Player.SlGet(sm, o, 2))) / 100;
                if ((w > 0) && (h > 0)) {
                    area += w * h;
                }
            }
            r = Model.RegionNext(orr, r);
        }
        return area;
    }
    internal static int SmIsTop(emon.Port.Cells on, int i) {
        // 1 when node i is a block of the flow that is a child of the document or of a section.
        int p = Model.NodeParent(on, i);
        if (p < 0) {
            return 0;
        }
        if ((Model.NodeKind(on, p) != Model.NkDocument()) && (Model.NodeKind(on, p) != Model.NkSection())) {
            return 0;
        }
        return SmAnchor(Model.NodeKind(on, i));
    }
    internal static int SmBelow(emon.Port.Cells on, int i, int a) {
        // 1 when node i is a descendant of node a.
        int q = Model.NodeParent(on, i);
        while (q >= 0) {
            if (q == a) {
                return 1;
            }
            q = Model.NodeParent(on, q);
        }
        return 0;
    }
    internal static int SmEarlier(emon.Port.Cells sm, int a, int b) {
        // 1 when candidate a comes before candidate b in reading order: its page, then its top.
        if (Player.SlGet(sm, a, 0) < Player.SlGet(sm, b, 0)) {
            return 1;
        }
        if ((Player.SlGet(sm, a, 0) == Player.SlGet(sm, b, 0)) && (Player.SlGet(sm, a, 2) < Player.SlGet(sm, b, 2))) {
            return 1;
        }
        return 0;
    }
    internal static int SmPending(emon.Port.Cells sm, emon.Port.Cells nm, int n0, emon.Port.Cells on, int i, int page, int y0, int mode) {
        // The next candidate to write before node i, -1 for none. `nm[n0 + o]` is the node a candidate is placed after (-1: none overlaps it). Mode 0: the
        // candidates placed after a node whose subtree has ended (i is later and not in it). Mode 1: those with no such node, whose top lies before (page, y0). Mode 2:
        // every one left. The earliest in reading order of those that qualify.
        int n = Player.SlCount(sm);
        int o = 0;
        int best = -1;
        int a = 0;
        int ok = 0;
        while (o < n) {
            if ((Player.SlGet(sm, o, 12) & 64) == 0) {
                a = emon.Port.CellsAt(nm, n0 + o);
                ok = 0;
                if (mode == 2) {
                    ok = 1;
                }
                if ((mode == 0) && (a >= 0)) {
                    if ((i > a) && (SmBelow(on, i, a) == 0)) {
                        ok = 1;
                    }
                }
                if ((mode == 1) && (a < 0)) {
                    if ((Player.SlGet(sm, o, 0) < page) || ((Player.SlGet(sm, o, 0) == page) && (Player.SlGet(sm, o, 2) < y0))) {
                        ok = 1;
                    }
                }
                if (ok == 1) {
                    if (best < 0) {
                        best = o;
                    } else if (SmEarlier(sm, o, best) == 1) {
                        best = o;
                    }
                }
            }
            o += 1;
        }
        return best;
    }
    internal static int SmSlHue(emon.Port.Cells sm, int o) {
        // The colour code of candidate `o`: the ink's `sm-hue`, or, for one read from pixels (flag 128), the code its group carried.
        if ((Player.SlGet(sm, o, 12) & 128) != 0) {
            return Player.SlGet(sm, o, 15);
        }
        return SmHue(Player.SlGet(sm, o, 15));
    }
    internal static int SmEmitFields(emon.Port.Cells et, int ts, int tl, int kind, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, int nn, emon.Port.Cells nm, int fb) {
        // The name and the date of the seal node `nn` whose text is `et[ts, ts + tl)` (`emon.sealfield`; the scratch is `nm` from cell `fb`): the name as read, the date as
        // `YYYY-MM-DD` when the text says year, month and day plainly, else as it stands.
        int start = 0;
        int j = 0;
        int form = 0;
        int v = 0;
        Sealfield.SfFields(et, ts, tl, kind, 0, nm, fb);
        if (emon.Port.CellsAt(nm, fb + 1) > 0) {
            start = emon.Port.CellsLen(text);
            while (j < emon.Port.CellsAt(nm, fb + 1)) {
                Model.TextAppendCp(text, emon.Port.CellsAt(et, emon.Port.CellsAt(nm, fb) + j));
                j += 1;
            }
            Model.NodeAddAttrText(nodes, attrs, nn, Model.FkName(), start, emon.Port.CellsAt(nm, fb + 1));
        }
        form = emon.Port.CellsAt(nm, fb + 2);
        if (form > 0) {
            start = emon.Port.CellsLen(text);
            if (form == 1) {
                v = emon.Port.CellsAt(nm, fb + 5);
                Model.TextAppendCp(text, 48 + ((v / 1000) % 10));
                Model.TextAppendCp(text, 48 + ((v / 100) % 10));
                Model.TextAppendCp(text, 48 + ((v / 10) % 10));
                Model.TextAppendCp(text, 48 + (v % 10));
                Model.TextAppendCp(text, 45);
                Model.TextAppendCp(text, 48 + (emon.Port.CellsAt(nm, fb + 6) / 10));
                Model.TextAppendCp(text, 48 + (emon.Port.CellsAt(nm, fb + 6) % 10));
                Model.TextAppendCp(text, 45);
                Model.TextAppendCp(text, 48 + (emon.Port.CellsAt(nm, fb + 7) / 10));
                Model.TextAppendCp(text, 48 + (emon.Port.CellsAt(nm, fb + 7) % 10));
                Model.NodeAddAttrText(nodes, attrs, nn, Model.FkDate(), start, 10);
            } else {
                j = 0;
                while (j < emon.Port.CellsAt(nm, fb + 4)) {
                    Model.TextAppendCp(text, emon.Port.CellsAt(et, emon.Port.CellsAt(nm, fb + 3) + j));
                    j += 1;
                }
                Model.NodeAddAttrText(nodes, attrs, nn, Model.FkDate(), start, emon.Port.CellsAt(nm, fb + 4));
            }
        }
        return 0;
    }
    internal static int SmEmit(emon.Port.Cells sm, int o, emon.Port.Cells et, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, int parent, emon.Port.Cells nm, int fb) {
        // Write candidate `o` as a `seal` node, the last child of `parent`: its subkind, confidence, source, region, the words as `text` (flagged `low-conf`),
        // its name and date (`sm-emit-fields`) and its colour name. `nm` from cell `fb` is the fields' scratch.
        int nn = Model.NodeNew(nodes, Model.NkSeal(), parent);
        int tl = Player.SlGet(sm, o, 14);
        int ts = Player.SlGet(sm, o, 13);
        int fl = Player.SlGet(sm, o, 12);
        int hue = SmSlHue(sm, o);
        int start = 0;
        int j = 0;
        emon.Port.CellsSet(sm, (o * 16) + 12, fl | 64);
        if (nn < 0) {
            return -1;
        }
        Model.NodeSetSub(nodes, nn, Player.SlGet(sm, o, 5));
        Model.NodeSetConf(nodes, nn, Player.SlGet(sm, o, 9));
        Model.NodeAddSrc(nodes, nn, Model.SrInfer());
        Model.NodeAddRegion(nodes, regions, nn, Player.SlGet(sm, o, 0), Player.SlGet(sm, o, 1), Player.SlGet(sm, o, 2), Player.SlGet(sm, o, 3), Player.SlGet(sm, o, 4));
        if (tl > 0) {
            start = emon.Port.CellsLen(text);
            // the node's text has the words of a pixel-read ring and not the marks it puts between them (they are a word of their own to a reader of the text); the fields below see them
            while (j < tl) {
                if (((fl & 128) != 0) && ((j > 0) && (((j + 1) < tl) && ((emon.Port.CellsAt(et, ts + (j - 1)) == 32) && ((emon.Port.CellsAt(et, ts + (j + 1)) == 32) && (SmPxDash(emon.Port.CellsAt(et, ts + j)) == 1)))))) {
                    j += 2;
                } else {
                    Model.TextAppendCp(text, emon.Port.CellsAt(et, ts + j));
                    j += 1;
                }
            }
            Model.NodeSetText(nodes, nn, start, emon.Port.CellsLen(text) - start);
            Model.NodeAddFlag(nodes, nn, Model.FlLowConf());
            if ((fl & 32) != 0) {
                Model.NodeAddSrc(nodes, nn, Model.SrText());
            } else {
                Model.NodeAddSrc(nodes, nn, Model.SrOcr());
            }
            SmEmitFields(et, ts, tl, Player.SlGet(sm, o, 5), nodes, attrs, text, nn, nm, fb);
        }
        if (hue >= 0) {
            start = emon.Port.CellsLen(text);
            j = 0;
            while (j < SmNameLen(hue)) {
                Model.TextAppendCp(text, SmNames[SmNameOff(hue) + j]);
                j += 1;
            }
            Model.NodeAddAttrText(nodes, attrs, nn, Model.FkColor(), start, SmNameLen(hue));
        }
        return nn;
    }
    internal static int SmTailParent(emon.Port.Cells on, emon.Port.Cells nm, int last) {
        // The new node of the nearest document or section above (or at) old node `last`: what a seal left at the end is a child of (an ancestor of the last node
        // written, so the Model's preorder holds).
        int q = last;
        int kq = 0;
        while (q >= 0) {
            kq = Model.NodeKind(on, q);
            if ((kq == Model.NkDocument()) || (kq == Model.NkSection())) {
                return emon.Port.CellsAt(nm, q);
            }
            q = Model.NodeParent(on, q);
        }
        return emon.Port.CellsAt(nm, 0);
    }
    public static int SmWrite(emon.Port.Cells sm, emon.Port.Cells et, emon.Port.Cells on, emon.Port.Cells oa, emon.Port.Cells orr, emon.Port.Cells text, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells nm) {
        // Copy the old Model's trees (`on oa orr`) into the empty arenas `nodes attrs regions`, in the same order, with a `seal` node for every candidate of `sm`.
        // WHERE: a candidate is drawn over the text it belongs to, and the document's own order puts it after that text (the stamp over the last lines of a paragraph,
        // the signature over the typed name). So it is written AFTER the last top-level block (a child of the document or of a section) whose region on its page
        // overlaps its box, after that block's subtree; a candidate that overlaps none is written before the first top-level block that starts below its top (the
        // later page's too). What is left is the last children of the nearest document or section above the last node written, before the first second root
        // (furniture). `nm` is scratch. Answers the seals written; the caller swaps the arenas when it is more than 0 (and leaves the old ones when it is 0).
        if (Player.SlCount(sm) == 0) {
            return 0;
        }
        int n = Model.NodeCount(on);
        int ns = Player.SlCount(sm);
        int i = 0;
        int p = 0;
        int r = 0;
        int o = 0;
        int np = 0;
        int best = 0;
        int area = 0;
        int pick = 0;
        int placed = 0;
        emon.Port.CellsDrop(nodes, 0);
        emon.Port.CellsDrop(attrs, 0);
        emon.Port.CellsDrop(regions, 0);
        emon.Port.CellsDrop(nm, 0);
        while (i < n) {
            emon.Port.CellsPush(nm, -1);
            i += 1;
        }
        // the block each candidate overlaps, in nm[n + o]: the last of those that cover at least half as much of it as the one that covers most (a stamp drawn over
        // a table and the edge of the paragraph under it belongs to the table), when that is at least `sm-overlap` per cent of the candidate's box
        o = 0;
        while (o < ns) {
            best = 0;
            i = 0;
            while (i < n) {
                if (SmIsTop(on, i) == 1) {
                    r = Model.NodeRegionHead(on, i);
                    if (r >= 0) {
                        area = SmHit(sm, o, orr, r);
                        if (area > best) {
                            best = area;
                        }
                    }
                }
                i += 1;
            }
            pick = -1;
            if ((best * 100) >= ((((Player.SlGet(sm, o, 3) - Player.SlGet(sm, o, 1)) / 100) * ((Player.SlGet(sm, o, 4) - Player.SlGet(sm, o, 2)) / 100)) * SmOverlap())) {
                i = 0;
                while (i < n) {
                    if (SmIsTop(on, i) == 1) {
                        r = Model.NodeRegionHead(on, i);
                        if (r >= 0) {
                            if ((SmHit(sm, o, orr, r) * 2) >= best) {
                                if (best > 0) {
                                    pick = i;
                                }
                            }
                        }
                    }
                    i += 1;
                }
            }
            emon.Port.CellsPush(nm, pick);
            o += 1;
        }
        Sealfield.SfPrep(nm, n + ns);
        i = 0;
        while (i < n) {
            p = Model.NodeParent(on, i);
            // candidates whose block (and its subtree) is behind us
            o = SmPending(sm, nm, n, on, i, 0, 0, 0);
            while (o >= 0) {
                np = emon.Port.CellsAt(nm, Model.NodeParent(on, emon.Port.CellsAt(nm, n + o)));
                SmEmit(sm, o, et, nodes, attrs, regions, text, np, nm, n + ns);
                placed += 1;
                o = SmPending(sm, nm, n, on, i, 0, 0, 0);
            }
            // the first second root: whatever is left goes before it
            if ((p < 0) && (i > 0)) {
                np = SmTailParent(on, nm, i - 1);
                o = SmPending(sm, nm, n, on, i, 0, 0, 2);
                while (o >= 0) {
                    SmEmit(sm, o, et, nodes, attrs, regions, text, np, nm, n + ns);
                    placed += 1;
                    o = SmPending(sm, nm, n, on, i, 0, 0, 2);
                }
            }
            // candidates that overlap no block: before the first top-level block that starts below their top
            if (SmIsTop(on, i) == 1) {
                r = Model.NodeRegionHead(on, i);
                if (r >= 0) {
                    o = SmPending(sm, nm, n, on, i, Model.RegionPage(orr, r), Model.RegionY0(orr, r), 1);
                    while (o >= 0) {
                        SmEmit(sm, o, et, nodes, attrs, regions, text, emon.Port.CellsAt(nm, p), nm, n + ns);
                        placed += 1;
                        o = SmPending(sm, nm, n, on, i, Model.RegionPage(orr, r), Model.RegionY0(orr, r), 1);
                    }
                }
            }
            if (p < 0) {
                Restruct.RsNode(on, oa, orr, nodes, attrs, regions, nm, i, -1);
            } else {
                Restruct.RsNode(on, oa, orr, nodes, attrs, regions, nm, i, emon.Port.CellsAt(nm, p));
            }
            i += 1;
        }
        // after the last node: the candidates left
        np = SmTailParent(on, nm, n - 1);
        o = SmPending(sm, nm, n, on, n, 0, 0, 2);
        while (o >= 0) {
            SmEmit(sm, o, et, nodes, attrs, regions, text, np, nm, n + ns);
            placed += 1;
            o = SmPending(sm, nm, n, on, n, 0, 0, 2);
        }
        emon.Port.CellsDrop(nm, n);
        Restruct.RsRemap(attrs, nm);
        return placed;
    }
}
